        # system_prompt に推論指示がなければ末尾に追加
        if agent.system_prompt and _THINKING_INSTRUCTION not in agent.system_prompt:
            agent.system_prompt = agent.system_prompt.rstrip() + "\n" + _THINKING_INSTRUCTION
