@cmd_registry.register("model", "モデルの確認・切替 (/model 1|2|<名前>)")
def cmd_model(agent: GeminiAgent, args: str):
    if not args:
        current = agent.rotator.accounts[0].model
        safe_print("  利用可能なモデル:")
        for num, name, desc in MODEL_LIST:
            marker = " <<" if name == current else ""
            safe_print(f"    {num}: {desc}{marker}")
        safe_print("  切替例: /model 1")
        return
    matched = None
    for num, name, desc in MODEL_LIST:
        if args == num or args == name:
            matched = (name, desc)
            break
    if matched:
        new_model, desc = matched
        for acc in agent.rotator.accounts:
            acc.model = new_model
        agent.clear_history()
        safe_print(f"  モデル変更: {desc}")
        safe_print("  会話履歴をリセットしました。")
    else:
        for acc in agent.rotator.accounts:
            acc.model = args
        agent.clear_history()
        safe_print(f"  モデルを変更しました: {args}")
        safe_print("  会話履歴をリセットしました。")

@cmd_registry.register("cd", "作業フォルダの確認・変更 (/cd <パス>)")
def cmd_cd(agent: GeminiAgent, args: str):
    if not args:
        safe_print(f"  現在の作業フォルダ: {agent.cwd}")
        return
    new_path = args.strip().strip('"').strip("'")
    expanded = str(Path(new_path).expanduser().resolve())
    if Path(expanded).exists():
        agent.set_cwd(expanded)
    else:
        safe_print(f"  フォルダが見つかりません: {expanded}")

@cmd_registry.register("task", "タスクの確認・開始 (/task <ゴール> | end)")
def cmd_task(agent: GeminiAgent, args: str):
    if args.lower() == "end":
        agent.end_task()
        safe_print("  タスクを終了しました。")
    elif args:
        agent.start_task(args)
        safe_print(f"  タスク開始: {args}")
    else:
        if agent._task_goal:
            safe_print(f"  現在のタスク: {agent._task_goal}")
        else:
            safe_print("  タスクなし（/task <ゴール> で開始）")

